cat > Sources/TMDBApp/Views/MovieListView.swift <<'EOF'
import SwiftUI

struct MovieListView: View {
    @State private var viewModel: MovieListViewModel

    init(viewModel: MovieListViewModel) {
        _viewModel = State(initialValue: viewModel)
    }

    var body: some View {
        content
            .navigationTitle("Popular")
            .task { await viewModel.load() }
    }

    @ViewBuilder
    private var content: some View {
        switch viewModel.state {
        case .idle, .loading:
            ProgressView().frame(maxWidth: .infinity, maxHeight: .infinity)
        case .empty:
            ContentUnavailableView("No movies", systemImage: "film")
        case .failed(let message):
            ContentUnavailableView {
                Label("Couldn't load movies", systemImage: "exclamationmark.triangle")
            } description: {
                Text(message)
            } actions: {
                Button("Retry") { Task { await viewModel.refresh() } }
            }
        case .loaded(let movies):
            List {
                ForEach(movies) { movie in
                    MovieRowView(movie: movie)
                        .task { await viewModel.loadNextPageIfNeeded(currentItem: movie) }
                }
                if let message = viewModel.paginationErrorMessage {
                    Text(message).font(.footnote).foregroundStyle(.secondary)
                }
            }
            #if os(iOS)
            .listStyle(.plain)
            #endif
            .refreshable { await viewModel.refresh() }
        }
    }
}
